#include <bits/stdc++.h>
#define LOOP(i,a,b) for(int i=(a);i<=(b);i++)
#define REVERSE(i,a,b) for(int i=(a);i>=(b);i--)
using namespace std;
const int MAX=505;
int n,m,mod;
int normalize(int x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void combine(int &x,int y){
	x=normalize(x+y);
}
int fast_pow(int base,int exp){
	int result=1;
	while(exp){
		if(exp&1)result=1ll*result*base%mod;
		base=1ll*base*base%mod;
		exp>>=1;
	}
	return result;
}
int fact[MAX*4],inv_fact[MAX*4];
void prepare(int n){
	fact[0]=1;
	LOOP(i,1,n)fact[i]=1ll*fact[i-1]*i%mod;
	inv_fact[n]=fast_pow(fact[n],mod-2);
	REVERSE(i,n-1,0)inv_fact[i]=1ll*inv_fact[i+1]*(i+1)%mod;
}
int choose(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*fact[n]*inv_fact[n-m]%mod*inv_fact[m]%mod;
}
vector<int> poly_f,g_poly;
int sum_series(int x){
	return x*(x+1)/2;
}
vector<int> multiply_poly(const vector<int> &A,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	LOOP(i,0,(int)A.size()-1)LOOP(j,0,(int)B.size()-1)combine(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int comb_series(int n,int m){
	return choose(n+m-1,n-1);
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	prepare(m<<1);
	poly_f.resize(n+1);g_poly.resize(n+1);
	poly_f[0]=1;
	LOOP(i,1,n){
		LOOP(j,0,i-1)combine(poly_f[i],1ll*poly_f[j]*poly_f[i-1-j]%mod*choose(i-1,j)%mod);
		poly_f[i]=1ll*poly_f[i]*(i+1)%mod;
	}
	LOOP(i,1,n){
		LOOP(j,0,i-1)combine(g_poly[i],(2ll*poly_f[j]*g_poly[i-1-j]%mod*choose(i-1,j)%mod*(i+1)%mod+1ll*choose(i-1,j)*(sum_series(j)+sum_series(i-1-j))%mod*poly_f[j]%mod*poly_f[i-1-j]%mod)%mod);
	}
	poly_f[0]=0;
	LOOP(i,0,n)g_poly[i]=1ll*g_poly[i]*inv_fact[i]%mod;
	LOOP(i,0,n)poly_f[i]=1ll*poly_f[i]*inv_fact[i]%mod;
	int answer=0;
	LOOP(i,1,m-n+1){
		combine(answer,1ll*g_poly[n]*comb_series(i+1,m-n-i+1)%mod*fact[n]%mod*i%mod);
		g_poly=multiply_poly(g_poly,poly_f);g_poly.resize(n+1);
	}
	cout<<answer;
	return 0;
}
